import { Outlet } from "react-router-dom";
import HeaderDefault from "./HeaderDefault";

const DefaultLayout = () => {
    return (
        <>
            <Layout>
                <Header
                    style={{
                        display: 'flex',
                        alignItems: 'center',
                    }}
                >
                    <div className="demo-logo" />
                    <Menu
                        theme="dark"
                        mode="horizontal"
                        defaultSelectedKeys={['2']}
                        items={items}
                        style={{
                            flex: 1,
                            minWidth: 0,
                        }}
                    />
                </Header>
                <Content
                    style={{
                        padding: '0 48px',
                    }}
                >
                    <Outlet></Outlet>
                </Content>
                <Footer
                    style={{
                        textAlign: 'center',
                    }}
                >
                    Ant Design ©{new Date().getFullYear()} Created by Ant UED
                </Footer>
            </Layout>
        </>
    )
};

export default DefaultLayout;
